    ["|cnPURE_BLUE_COLOR:(Quest)|r %s"] = "|cnPURE_BLUE_COLOR:(Квест)|r %s",
    ["|cnPURE_GREEN_COLOR:<Shift click to view Frequently Asked Questions in your browser>|r"] = "|cnPURE_GREEN_COLOR:<Shift + клацання — відкрити поширені запитання у браузері>|r",
    ["|cnRED_FONT_COLOR:%d|r/%d"] = "|cnRED_FONT_COLOR:%d|r/%d",
    ["|cnRED_FONT_COLOR:This feature is not currently available.|r"] = "|cnRED_FONT_COLOR:Ця функція наразі недоступна.|r",
    ["|cnRED_FONT_COLOR:This is not your preferred armor type.|r"] = "|cnRED_FONT_COLOR:Цей тип броні не є основним для вас.|r",
    ["|cnRED_FONT_COLOR:You can't edit chat settings while chat is disabled.|r\r\n|cnGREEN_FONT_COLOR:<Shift Click to View Options>|r"] = "|cnRED_FONT_COLOR:Ви не можете редагувати налаштування чату, поки чат вимкнено.|r\r\n|cnGREEN_FONT_COLOR:<Shift Натисніть, щоб переглянути параметри>|r",
    ["|cnRED_FONT_COLOR:You cannot equip this item.|r|n|nIts appearance will be added to your collection and it will become Account bound until equipped."] = "|cnRED_FONT_COLOR:Ви не можете екіпірувати цей предмет.|r|n|nЙого зовнішній вигляд буде додано до вашої колекції та буде прив'язаний до облікового запису, доки його не буде екіпіровано.",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Aggro|r comes with its own visual effect and a |cnTUTORIAL_BLUE_FONT_COLOR:sense of progression.|r"] = "|cnTUTORIAL_BLUE_FONT_COLOR:Аґро|r має власний візуальний ефект та |cnTUTORIAL_BLUE_FONT_COLOR:відчуття прогресу.|r",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Ping directly|r onto a creature or character."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Позначайте|r істоту або персонажа безпосередньо.",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Press and Hold|r your ping key to select a specific ping."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Натисніть і утримуйте|r клавішу позначки, щоб вибрати її тип.",
