    ["|Hplayer:%s|h[%s]|h was burnt to a crisp by lava in %s! They were level %d"] = "|Hplayer:%s|h[%s]|h згоряє в лаві у %s! Рівень персонажа: %d",
    ["|Hplayer:%s|h[%s]|h was burnt to death by fire in %s! They were level %d"] = "|Hplayer:%s|h[%s]|h згоряє у вогні в %s! Рівень персонажа: %d",
